template:
% 参数由系统自动注入：\def\showasym{1} \def\showzeros{1} \def\showperiod{1}
% 固定视图：x 约 [-3π/2,3π/2] 显示三个分支，y 约 [-3,3]
\pgfmathsetmacro{\xright}{3*pi/2+0.6}
\pgfmathsetmacro{\xleft}{-\xright}
\pgfmathtruncatemacro{\ytop}{3}
\pgfmathtruncatemacro{\ybottom}{-3}
% 分支端点：tan 值到达视图上边处截断（atan 以度为单位返回，rad 转弧度）
\pgfmathsetmacro{\edge}{rad(atan(\ytop+0.3))}
\pgfmathsetmacro{\xrange}{\xright-\xleft}
\pgfmathsetmacro{\yrange}{\ytop-\ybottom}
\pgfmathsetmacro{\figscale}{6.5/max(\xrange,\yrange)}
\pgfmathsetmacro{\dotr}{1.6/\figscale}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  % ===== 坐标系 =====
  \draw[->, thick] (\xleft-0.6,0) -- (\xright+0.8,0) node[right] {$x$};
  \draw[->, thick] (0,\ybottom-0.5) -- (0,\ytop+0.6) node[above] {$y$};
  % x 轴刻度：π/2 整数倍 % ===== 渐近线 x=±π/2、±3π/2 =====
  \ifnum\showasym>0
    \draw[dashed, gray] (pi/2,\ybottom-0.4) -- (pi/2,\ytop+0.4);
    \draw[dashed, gray] (-pi/2,\ybottom-0.4) -- (-pi/2,\ytop+0.4);
    \draw[dashed, gray] (3*pi/2,\ybottom-0.4) -- (3*pi/2,\ytop+0.4);
    \draw[dashed, gray] (-3*pi/2,\ybottom-0.4) -- (-3*pi/2,\ytop+0.4);
  \fi
  % ===== 三个分支 y=tan x =====
  \draw[thick, domain=-\edge:\edge, samples=80, smooth] plot (\x, {tan(deg(\x))});
  \draw[thick, domain={pi/2+\edge}:{3*pi/2-\edge}, samples=80, smooth] plot (\x, {tan(deg(\x))});
  \draw[thick, domain={-3*pi/2+\edge}:{-pi/2-\edge}, samples=80, smooth] plot (\x, {tan(deg(\x))});
  \node[font=\tiny, anchor=north east, gray!50!black] at (\xright-0.2,\ytop-0.2) {$y=\tan x$};
  % ===== 零点 =====
  \ifnum\showzeros>0
    \fill (pi,0) circle [radius=\dotr pt];
    \fill (-pi,0) circle [radius=\dotr pt];
  \fi
  % ===== 周期 T=π =====
  \ifnum\showperiod>0
    \pgfmathsetmacro{\yar}{\ybottom+0.5}
    \draw[<->, thick] (-pi/2,\yar) -- (pi/2,\yar);
    \draw (-pi/2,\yar-0.12) -- (-pi/2,\yar+0.12);
    \draw (pi/2,\yar-0.12) -- (pi/2,\yar+0.12);
    \node[below, font=\tiny] at (0,\yar) {$T=\pi$};
  \fi
\end{tikzpicture}
